      backup_text =
        "type Image = ? in\n\
         # Representing column names as projection functions for better error \
         localization since we don't do first-class labels #\n\
         let scatter_plot\n\
         : poly row -> ([row], row -> Int, row -> Int) -> Image =\n\
        \  ? in\n\
         # Using ? for the categorical variables #\n\
         let pie_chart\n\
         : poly row -> ([row], row -> ?, row -> Int) -> Image =\n\
        \  ? in\n\n\
         let brown_get_acne =\n\
        \  type JellyNamed = (\n\
        \    name= String,\n\
        \    get_acne= Bool,\n\
        \    red= Bool,\n\
        \    black= Bool,\n\
        \    white= Bool,\n\
        \    green= Bool,\n\
        \    yellow= Bool,\n\
        \    brown= Bool,\n\
        \    orange= Bool,\n\
        \    pink= Bool,\n\
        \    purple= Bool\n\
        \  ) in\n\
        \  let jellyNamed : [JellyNamed] = (\n\
        \    [\n\
        \      (\"Emily\",    true, false, false, false, true, false, false, \
         true, false, false),\n\
        \      (\"Jacob\",    true, false, true, false, true, true, false, \
         false, false, false),\n\
        \      (\"Emma\",     false, false, false, false, true, false, false, \
         false, true, false),\n\
        \      (\"Aidan\",    false, false, false, false, false, true, false, \
         false, false, false),\n\
        \      (\"Madison\",  false, false, false, false, false, true, false, \
         false, true, false),\n\
        \      (\"Ethan\",    true, false, true, false, false, false, false, \
         true, true, false),\n\
        \      (\"Hannah\",   false, false, true, false, false, false, false, \
         false, true, false),\n\
        \      (\"Matthew\",  true, false, false, false, false, false, true, \
         true, false, false),\n\
        \      (\"Hailey\",   true, false, false, false, false, false, false, \
         true, false, false),\n\
        \      (\"Nicholas\", false, true, false, false, false, true, true, \
         false, true, false)\n\
        \    ]\n\
        \  ) in\n\
        \  let brown_and_get_acne =\n\
        \    fun r : JellyNamed -> r.brown && r.get_acne in\n\
        \  let count = (\n\
        \    typfun row ->\n\
        \      typfun v ->\n\
        \        fun (t1 : [row], proj : row -> v) ->\n\
        \          let go =\n\
        \            fun (groups : [(value= v, count= Int)], row : row) ->\n\
        \              case find_opt(groups, fun g -> g.value == proj(row))\n\
        \              | None => (value= proj(row), count= 1) :: groups\n\
        \              | Some(value=v,count=c) =>\n\
        \                (value= proj(row), count= c + 1)\n\
        \                :: filter(groups, fun g -> g.value != proj(row))\n\
        \              end in\n\
        \          fold_left(t1, go, []) : [(value= v, count= Int)]\n\
        \  ) in\n\
        \  let build_column\n\
        \  : poly r1 ->\n\
        \    poly r2 ->\n\
        \      poly r3 -> ([r1], r1 -> r2, (r1, r2) -> r3) -> [r3] = (\n\
        \    typfun r1 ->\n\
        \      typfun r2 ->\n\
        \        typfun r3 ->\n\
        \          fun (table, project, build_result) ->\n\
        \            map(table, fun r : r1 -> build_result(r, project(r)))\n\
        \  ) in\n\
        \  let incorrect =\n\
        \    let brown_and_get_acne_table =\n\
        \      build_column@<JellyNamed>@<Bool>@<(\n\
        \        name= String,\n\
        \        get_acne= Bool,\n\
        \        red= Bool,\n\
        \        black= Bool,\n\
        \        white= Bool,\n\
        \        green= Bool,\n\
        \        yellow= Bool,\n\
        \        brown= Bool,\n\
        \        orange= Bool,\n\
        \        pink= Bool,\n\
        \        purple= Bool,\n\
        \        part2= Bool\n\
        \      )>(\n\
        \        jellyNamed,\n\
        \        brown_and_get_acne,\n\
        \        fun (t, v) -> t ... (part2= v)\n\
        \      ) in\n\
        \    count@<(\n\
        \      name= String,\n\
        \      get_acne= Bool,\n\
        \      red= Bool,\n\
        \      black= Bool,\n\
        \      white= Bool,\n\
        \      green= Bool,\n\
        \      yellow= Bool,\n\
        \      brown= Bool,\n\
        \      orange= Bool,\n\
        \      pink= Bool,\n\
        \      purple= Bool,\n\
        \      part2= Bool\n\
        \    )>@<Bool>(\n\
        \      brown_and_get_acne_table,\n\
        \      fun r -> r.`brown and get acne`\n\
        \    ) in\n\
        \  let correct =\n\
        \    let brown_and_get_acne_table =\n\
        \      build_column@<JellyNamed>@<Bool>@<(\n\
        \        name= String,\n\
        \        get_acne= Bool,\n\
        \        red= Bool,\n\
        \        black= Bool,\n\
        \        white= Bool,\n\
        \        green= Bool,\n\
        \        yellow= Bool,\n\
        \        brown= Bool,\n\
        \        orange= Bool,\n\
        \        pink= Bool,\n\
        \        purple= Bool,\n\
        \        `brown and get acne`= Bool\n\
        \      )>(\n\
        \        jellyNamed,\n\
        \        brown_and_get_acne,\n\
        \        fun (t, v) -> t ... (`brown and get acne`= v)\n\
        \      ) in\n\
        \    count@<(\n\
        \      name= String,\n\
        \      get_acne= Bool,\n\
        \      red= Bool,\n\
        \      black= Bool,\n\
        \      white= Bool,\n\
        \      green= Bool,\n\
        \      yellow= Bool,\n\
        \      brown= Bool,\n\
        \      orange= Bool,\n\
